/**
 * Inline figure node.
 *
 * Shapes are generated by Slaids from a small typed spec, never from foreign
 * markup, so they can live safely in any content field.
 */

import { Node, mergeAttributes } from '@tiptap/core'
import { NodeViewWrapper, ReactNodeViewRenderer, type NodeViewProps } from '@tiptap/react'
import { DEFAULT_SHAPE_HEIGHT, shapeFromNode } from '../../domain/richdoc'
import type { ShapeKind } from '../../domain/types'
import { ShapeView } from '../slide/ShapeView'
import { findSelectedNodePos } from './SlaidsImageExtension'

declare module '@tiptap/core' {
  interface Commands<ReturnType> {
    slaidsShape: {
      insertSlaidsShape: (attrs?: { kind?: ShapeKind; fill?: string; stroke?: string }) => ReturnType
      updateSlaidsShape: (attrs: Record<string, unknown>) => ReturnType
    }
  }
}

export const SHAPE_HEIGHT_PRESETS = [100, 160, 240, 320] as const

function ShapeNodeView({ node }: NodeViewProps) {
  const height = Number(node.attrs.height)
  return (
    <NodeViewWrapper
      className="rd-shape-wrapper"
      style={{ height: Number.isFinite(height) && height > 0 ? height : DEFAULT_SHAPE_HEIGHT }}
    >
      <ShapeView shape={shapeFromNode({ type: 'slaidsShape', attrs: node.attrs })} />
    </NodeViewWrapper>
  )
}

export const SlaidsShapeExtension = Node.create({
  name: 'slaidsShape',
  group: 'block',
  atom: true,
  draggable: true,

  addAttributes() {
    return {
      kind: { default: 'rectangle' },
      fill: { default: '#bfccd9' },
      stroke: { default: '#263340' },
      strokeWidth: { default: 3 },
      height: { default: DEFAULT_SHAPE_HEIGHT },
    }
  },

  parseHTML() {
    return [{ tag: 'figure[data-shape-kind]' }]
  },

  renderHTML({ HTMLAttributes }) {
    return ['figure', mergeAttributes(HTMLAttributes, { 'data-shape-kind': HTMLAttributes.kind })]
  },

  addNodeView() {
    return ReactNodeViewRenderer(ShapeNodeView)
  },

  addCommands() {
    return {
      insertSlaidsShape:
        (attrs) =>
        ({ commands }) =>
          commands.insertContent({ type: this.name, attrs: { ...attrs } }),
      updateSlaidsShape:
        (attrs) =>
        ({ state, dispatch, tr }) => {
          const pos = findSelectedNodePos(state, this.name)
          if (pos === null) return false
          const node = state.doc.nodeAt(pos)
          if (!node) return false
          if (dispatch) tr.setNodeMarkup(pos, undefined, { ...node.attrs, ...attrs })
          return true
        },
    }
  },
})
